    <style>
      :root {
        color-scheme: light;
        --bg: #f6f7fb;
        --surface: #ffffff;
        --surface-soft: #f1f5f9;
        --text: #172033;
        --muted: #667085;
        --border: #e4e7ec;
        --danger: #dc2626;
        --danger-dark: #b91c1c;
        --shadow: 0 24px 70px rgba(15, 23, 42, 0.16);
        --radius: 28px;
