        min-height: 100vh;
        margin: 0;
        font-family:
          Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont,
          "Segoe UI", sans-serif;
        color: var(--text);
        background:
          radial-gradient(circle at top left, rgba(99, 102, 241, 0.18), transparent 32rem),
          linear-gradient(135deg, #f8fafc 0%, var(--bg) 100%);
      }

