        width: min(1120px, calc(100% - 32px));
        margin: 0 auto;
        padding: 48px 0;
      }

      .topbar {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        margin-bottom: 32px;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 12px;
        font-weight: 800;
        letter-spacing: -0.04em;
      }

      .brand-mark {
        display: grid;
        width: 40px;
        height: 40px;
        place-items: center;
        color: #ffffff;
        background: #111827;
        border-radius: 14px;
        box-shadow: 0 12px 30px rgba(17, 24, 39, 0.16);
      }

      .eyebrow {
        margin: 0 0 10px;
        color: #4f46e5;
        font-size: 0.82rem;
        font-weight: 800;
        letter-spacing: 0.12em;
        text-transform: uppercase;
      }

      .layout {
        display: grid;
        grid-template-columns: minmax(0, 1fr) 340px;
        gap: 28px;
        align-items: start;
      }

      .preview-card,
      .details-card {
        background: rgba(255, 255, 255, 0.88);
        border: 1px solid rgba(255, 255, 255, 0.84);
        border-radius: var(--radius);
        box-shadow: var(--shadow);
        backdrop-filter: blur(20px);
      }

      .preview-card {
        overflow: hidden;
      }

      .image-frame {
        padding: 16px;
        background: linear-gradient(135deg, #e0e7ff, #f8fafc);
      }

      .image-frame img {
        display: block;
        width: 100%;
        aspect-ratio: 16 / 10;
        object-fit: cover;
        border-radius: 20px;
        box-shadow: 0 18px 50px rgba(15, 23, 42, 0.2);
      }

      .preview-content {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 20px;
        padding: 24px;
      }

      h1,
      h2,
      p {
        margin-top: 0;
      }

      h1 {
        margin-bottom: 8px;
        font-size: clamp(2rem, 5vw, 4rem);
        line-height: 0.96;
        letter-spacing: -0.08em;
      }

      h2 {
        margin-bottom: 10px;
        font-size: 1.2rem;
        letter-spacing: -0.035em;
      }

      .description,
      .meta {
        color: var(--muted);
        line-height: 1.6;
      }

      .description {
        max-width: 620px;
        margin-bottom: 0;
      }

      .details-card {
        padding: 24px;
      }

      .metadata {
        display: grid;
        gap: 16px;
        margin: 24px 0 0;
        padding: 0;
        list-style: none;
      }

      .metadata li {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 16px;
        padding-bottom: 14px;
        border-bottom: 1px solid var(--border);
      }

      .metadata li:last-child {
        padding-bottom: 0;
        border-bottom: 0;
      }

      .metadata span:first-child {
        color: var(--muted);
      }

      .metadata span:last-child {
        font-weight: 700;
      }

      .button {
        display: inline-flex;
        min-height: 44px;
        align-items: center;
        justify-content: center;
        gap: 8px;
        padding: 0 18px;
        border: 0;
        border-radius: 999px;
        cursor: pointer;
        font-weight: 800;
        transition:
          transform 160ms ease,
          box-shadow 160ms ease,
          background 160ms ease;
      }

      .button:hover {
        transform: translateY(-1px);
      }

      .button-primary {
        color: #ffffff;
        background: #111827;
        box-shadow: 0 12px 24px rgba(17, 24, 39, 0.18);
      }

      .button-danger {
        color: #ffffff;
        background: var(--danger);
        box-shadow: 0 12px 24px rgba(220, 38, 38, 0.2);
      }

      .button-danger:hover {
        background: var(--danger-dark);
      }

      .button-secondary {
        color: var(--text);
        background: var(--surface-soft);
      }

      .trigger {
        white-space: nowrap;
      }

      .modal-root[hidden] {
        display: none;
      }

      .modal-root {
        position: fixed;
        inset: 0;
        z-index: 10;
      }

      .modal-backdrop {
        position: absolute;
        inset: 0;
        background: rgba(15, 23, 42, 0.58);
        backdrop-filter: blur(10px);
      }

      .modal-panel-wrap {
        position: relative;
        display: grid;
        min-height: 100%;
        place-items: center;
        padding: 24px;
      }

      .modal-panel {
        width: min(100%, 460px);
        padding: 28px;
        background: var(--surface);
        border: 1px solid rgba(255, 255, 255, 0.9);
        border-radius: 26px;
        box-shadow: 0 32px 90px rgba(15, 23, 42, 0.32);
      }

      .modal-icon {
        display: grid;
        width: 56px;
        height: 56px;
        margin-bottom: 18px;
        place-items: center;
        color: var(--danger);
        background: #fee2e2;
        border-radius: 18px;
        font-size: 1.6rem;
        font-weight: 900;
      }

      .modal-panel h2 {
        margin-bottom: 8px;
        font-size: 1.55rem;
      }

      .modal-panel p {
        margin-bottom: 24px;
        color: var(--muted);
        line-height: 1.6;
      }

      .modal-actions {
        display: flex;
        justify-content: flex-end;
        gap: 12px;
      }

      .status {
        min-height: 1.5em;
        margin-top: 18px;
        color: #047857;
        font-weight: 700;
      }

      @media (max-width: 820px) {
        .layout {
          grid-template-columns: 1fr;
        }

        .preview-content {
          align-items: flex-start;
          flex-direction: column;
        }

        .trigger {
          width: 100%;
        }
      }

      @media (max-width: 520px) {
        .app-shell {
          width: min(100% - 20px, 1120px);
          padding: 24px 0;
        }

        .topbar {
          margin-bottom: 22px;
        }

        .modal-actions {
          flex-direction: column-reverse;
        }

        .modal-actions .button {
          width: 100%;
        }
      }

      @media (prefers-reduced-motion: reduce) {
        *,
        *::before,
        *::after {
          scroll-behavior: auto !important;
          transition-duration: 0.01ms !important;
          animation-duration: 0.01ms !important;
          animation-iteration-count: 1 !important;
        }
      }
    </style>
  </head>
  <body>
    <div id="root"></div>

    <script>
      const image = {
        title: "Alpine lake at sunrise",
        description:
          "A high-resolution landscape saved to your image library for the Spring Campaign collection.",
        source:
          "https://images.unsplash.com/photo-1500530855697-b586d89ba3ee?auto=format&fit=crop&w=1400&q=80",
        size: "8.4 MB",
        type: "JPEG",
        collection: "Spring Campaign"
      };

      const state = {
        isDialogOpen: false,
        status: ""
      };

      let lastFocusedElement = null;

      function Button({ className = "", id = "", text, type = "button", ariaLabel = "" }) {
        const labelAttribute = ariaLabel ? ` aria-label="${ariaLabel}"` : "";
        const idAttribute = id ? ` id="${id}"` : "";

        return `<button${idAttribute} class="button ${className}" type="${type}"${labelAttribute}>${text}</button>`;
      }

      function Header() {
        return `
          <header class="topbar" aria-label="Library navigation">
            <div class="brand">
              <span class="brand-mark" aria-hidden="true">P</span>
              <span>Pixel Library</span>
            </div>
            ${Button({ className: "button-primary", text: "Share" })}
          </header>
        `;
      }

      function ImagePreview() {
        return `
          <section class="preview-card" aria-labelledby="image-title">
            <div class="image-frame">
              <img src="${image.source}" alt="A calm alpine lake with mountains reflected in the water at sunrise.">
            </div>
            <div class="preview-content">
              <div>
                <p class="eyebrow">Image preview</p>
                <h1 id="image-title">${image.title}</h1>
                <p class="description">${image.description}</p>
              </div>
              ${Button({
                id: "delete-trigger",
                className: "button-danger trigger",
                text: "Delete image",
                ariaLabel: "Delete Alpine lake at sunrise"
              })}
            </div>
          </section>
        `;
      }

      function ImageDetails() {
        return `
          <aside class="details-card" aria-labelledby="details-title">
            <h2 id="details-title">File details</h2>
            <p class="meta">Manage the selected asset before publishing it to your product gallery.</p>
            <ul class="metadata">
              <li><span>Collection</span><span>${image.collection}</span></li>
              <li><span>File type</span><span>${image.type}</span></li>
              <li><span>Size</span><span>${image.size}</span></li>
            </ul>
            <p class="status" role="status" aria-live="polite">${state.status}</p>
          </aside>
        `;
      }

      function ConfirmDeleteDialog() {
        return `
          <div
            id="delete-dialog-root"
            class="modal-root"
            role="presentation"
            ${state.isDialogOpen ? "" : "hidden"}
          >
            <div class="modal-backdrop" data-close-dialog></div>
            <div class="modal-panel-wrap">
              <section
                class="modal-panel"
                role="dialog"
                aria-modal="true"
                aria-labelledby="dialog-title"
                aria-describedby="dialog-description"
                tabindex="-1"
              >
                <div class="modal-icon" aria-hidden="true">!</div>
                <h2 id="dialog-title">Delete this image?</h2>
                <p id="dialog-description">
                  This will remove "${image.title}" from your library. This action cannot be undone.
                </p>
                <div class="modal-actions">
                  ${Button({ id: "cancel-delete", className: "button-secondary", text: "Cancel" })}
                  ${Button({ id: "confirm-delete", className: "button-danger", text: "Yes, delete it" })}
                </div>
              </section>
            </div>
          </div>
        `;
      }

      function App() {
        return `
          <main class="app-shell">
            ${Header()}
            <div class="layout">
              ${ImagePreview()}
              ${ImageDetails()}
            </div>
          </main>
          ${ConfirmDeleteDialog()}
        `;
      }

      function getFocusableElements(container) {
        return Array.from(
          container.querySelectorAll(
            'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
          )
        ).filter((element) => !element.hasAttribute("disabled") && !element.getAttribute("aria-hidden"));
      }

      function openDialog() {
        lastFocusedElement = document.activeElement;
        state.isDialogOpen = true;
        state.status = "";
        render();
        document.querySelector(".modal-panel").focus();
      }

      function closeDialog() {
        state.isDialogOpen = false;
        render();

        if (lastFocusedElement) {
          lastFocusedElement.focus();
        }
      }

      function confirmDelete() {
        state.isDialogOpen = false;
        state.status = "Image deleted from your library.";
        render();
      }

      function handleKeydown(event) {
        if (!state.isDialogOpen) {
          return;
        }

        if (event.key === "Escape") {
          event.preventDefault();
          closeDialog();
          return;
        }

        if (event.key !== "Tab") {
          return;
        }

        const dialog = document.querySelector(".modal-panel");
        const focusableElements = getFocusableElements(dialog);
        const firstElement = focusableElements[0];
        const lastElement = focusableElements[focusableElements.length - 1];

        if (event.shiftKey && document.activeElement === firstElement) {
          event.preventDefault();
          lastElement.focus();
        } else if (!event.shiftKey && document.activeElement === lastElement) {
          event.preventDefault();
          firstElement.focus();
        }
      }

      function bindEvents() {
        document.querySelector(".trigger").addEventListener("click", openDialog);
        document.addEventListener("keydown", handleKeydown);

        const cancelButton = document.getElementById("cancel-delete");
        const confirmButton = document.getElementById("confirm-delete");
        const backdrop = document.querySelector("[data-close-dialog]");

        if (cancelButton) {
          cancelButton.addEventListener("click", closeDialog);
        }

        if (confirmButton) {
          confirmButton.addEventListener("click", confirmDelete);
        }

        if (backdrop) {
          backdrop.addEventListener("click", closeDialog);
        }
      }

      function render() {
        document.getElementById("root").innerHTML = App();
        bindEvents();
      }

      render();
    </script>
  </body>
</html>
